/**
 * Version writer (spec L583): `package.json.version` is the single source and is
 * projected into the native projects. Android gets `versionName` plus a numeric
 * `versionCode`; iOS gets `CFBundleShortVersionString` plus `CFBundleVersion`
 * with the same integer — `major*10000 + minor*100 + patch`, so 1.2.3 → 10203.
 *
 * The native projects are generated by `mobile:add:*` and are absent on a fresh
 * clone, so a missing file is reported and skipped instead of failing the web
 * build. A malformed version, or one whose minor/patch would collide in the
 * packed encoding, fails loudly — a wrong build number is a store rejection.
 *
 * Usage: bun mobile/scripts/set-native-version.mjs [root]
 */
import { access, readFile, writeFile } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

const webRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..")
const root = process.argv[2] === undefined ? webRoot : path.resolve(process.argv[2])
const packageJsonPath = path.join(root, "package.json")

const VERSION_PATTERN = /^(\d+)\.(\d+)\.(\d+)$/

const raw = JSON.parse(await readFile(packageJsonPath, "utf8")).version
const match = VERSION_PATTERN.exec(String(raw ?? ""))

if (match === null) {
  console.error(
    `set-native-version: malformed version ${JSON.stringify(raw)} in ${packageJsonPath} — expected MAJOR.MINOR.PATCH`,
  )
  process.exit(1)
}

const major = Number(match[1])
const minor = Number(match[2])
const patchLevel = Number(match[3])

if (minor > 99 || patchLevel > 99) {
  console.error(
    `set-native-version: version ${raw} cannot be encoded as major*10000+minor*100+patch — minor and patch must each be 0-99`,
  )
  process.exit(1)
}

const version = `${major}.${minor}.${patchLevel}`
const versionCode = major * 10000 + minor * 100 + patchLevel

if (versionCode < 1) {
  console.error(
    `set-native-version: version ${raw} encodes to versionCode ${versionCode} — Android requires a positive integer, so set a real package.json version`,
  )
  process.exit(1)
}

async function exists(file) {
  try {
    await access(file)
    return true
  } catch {
    return false
  }
}

async function patch(file, edits) {
  if (!(await exists(file))) return false
  const before = await readFile(file, "utf8")
  let after = before
  for (const [pattern, replacement] of edits) after = after.replace(pattern, replacement)
  if (after === before) {
    console.warn(`set-native-version: no version fields matched in ${path.relative(root, file)}`)
    return true
  }
  await writeFile(file, after)
  console.log(`set-native-version: ${path.relative(root, file)} → ${version} (${versionCode})`)
  return true
}

const androidCandidates = ["mobile/android/app/build.gradle", "mobile/android/app/build.gradle.kts"]
let androidPatched = false
for (const candidate of androidCandidates) {
  const patched = await patch(path.join(root, candidate), [
    [/versionName\s+"[^"]*"/, `versionName "${version}"`],
    [/versionCode\s+\d+/, `versionCode ${versionCode}`],
  ])
  androidPatched = androidPatched || patched
}

const iosPatched = await patch(path.join(root, "mobile/ios/App/App/Info.plist"), [
  [/(<key>CFBundleShortVersionString<\/key>\s*<string>)[^<]*(<\/string>)/, `$1${version}$2`],
  [/(<key>CFBundleVersion<\/key>\s*<string>)[^<]*(<\/string>)/, `$1${versionCode}$2`],
])

if (!androidPatched && !iosPatched) {
  console.log(
    "set-native-version: no native projects present — run `bun run mobile:add:ios` / `mobile:add:android` first (web version is unaffected)",
  )
}
